{
  "metadati": {
    "data_sintetica": "2026-04-14",
    "chiave_indagine": null,
    "descrizione": "L'utente, delegato per la Rilevazione sulle tecnologie dell’informazione e della comunicazione nelle imprese (IST-01175), segnala che il recupero dell'accesso non si conclude perché non può accedere alla vecchia casella email. Il chatbot indica di sottoporre il problema all'assistenza affinché valuti l'aggiornamento del recapito."
  },
  "conversazione": [
    {
      "sender": "Utente",
      "testo": "Sono delegato per la Rilevazione sulle tecnologie dell’informazione e della comunicazione nelle imprese, codice PSN IST-01175. Devo recuperare l'accesso, ma nn riesco più ad aprire la vecchia casella email."
    },
    {
      "sender": "Agente",
      "testo": "Poiché il recupero dipende da una vecchia casella non accessibile, è opportuno sottoporre il problema all'assistenza, che potrà valutare la richiesta di aggiornamento del recapito."
    },
    {
      "sender": "Utente",
      "testo": "Ho già provato il recupero. Dopo l'eventuale aggiornamento riceverò un codice?"
    },
    {
      "sender": "Agente",
      "testo": "I passaggi successivi e la possibilità di inviare un codice vanno verificati con l'assistenza, insieme alla richiesta relativa alla vecchia casella."
    }
  ]
}
